import os
from datetime import date
from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential

def normalize_expense_document(file_path: str, endpoint: str = None, api_key: str = None) -> dict:
    endpoint = endpoint or os.environ.get("AZURE_FORM_RECOGNIZER_ENDPOINT")
    api_key = api_key or os.environ.get("AZURE_FORM_RECOGNIZER_API_KEY")

    if not endpoint or not api_key:
        raise ValueError("Azure Form Recognizer endpoint and API key are required.")

    client = DocumentAnalysisClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key)
    )

    with open(file_path, "rb") as document:
        poller = client.begin_analyze_document("prebuilt-receipt", document=document)
        result = poller.result()

    if not result.receipts:
        raise ValueError("No receipt or expense data detected in the provided document.")

    receipt = result.receipts[0]
    fields = receipt.fields

    def get_val(field_name):
        f = fields.get(field_name)
        return f.value if f else None

    def to_float(val):
        return float(val) if val is not None else 0.0

    def to_date_str(val):
        if isinstance(val, date):
            return val.isoformat()
        return str(val) if val else None

    line_items = []
    receipt_items = get_val("Items")
    if receipt_items:
        for item in receipt_items:
            iv = item.value
            line_items.append({
                "description": iv["Name"].value if "Name" in iv else None,
                "quantity": to_float(iv["Quantity"].value if "Quantity" in iv else None),
                "unit_price": to_float(iv["Price"].value if "Price" in iv else None),
                "total_price": to_float(iv["TotalPrice"].value if "TotalPrice" in iv else None)
            })

    return {
        "document_type": "expense_receipt",
        "vendor": {
            "name": get_val("MerchantName") or "Unknown",
            "address": get_val("MerchantAddress") or ""
        },
        "transaction": {
            "date": to_date_str(get_val("TransactionDate")),
            "currency": "USD",
            "subtotal": to_float(get_val("Subtotal")),
            "tax_amount": to_float(get_val("Tax")),
            "tip_amount": to_float(get_val("Tip")),
            "total_amount": to_float(get_val("Total"))
        },
        "line_items": line_items
    }
